/**
 * @public
 * Privacy data wrapper for telemetry data.
 */
declare interface IPrivacyData<T> {
    /** The actual value */
    _value: T;
    /** The type of privacy data */
    _type: IPrivacyDataType;
}

/**
 * @public
 * Privacy data type.
 * safe: The data is safe to log.
 * unsafe: The data is not safe to log and should be scrubbed or dropped.
 */
declare type IPrivacyDataType = 'safe' | 'unsafe';

/* Excluded from this release type: _IQos */

/**
 * @public
 */
declare interface IQosEndSchema {
    /**
     * This is the name of the qos event
     */
    name?: string;
    /**
     * This is a endTime override for the qos event
     */
    endTimeOverride?: number;
    /**
     * This is result code for the qos event
     */
    resultCode?: string;
    /**
     * This is the result type enum
     */
    resultType: ResultTypeEnum;
    /**
     * This is the error message to be logged with failed result
     */
    error?: string | IPrivacyData<string>;
    /**
     * An optional stack trace to be logged with the error
     */
    stackTrace?: IPrivacyData<string>;
    /**
     * This is the random extra data for the qos event
     */
    extraData?: IExtraData;
    /**
     * Extra data for the qos event that should be logged as aggregatable metrics
     */
    extraMetrics?: IExtraData;
    /**
     * The object type against which the event was invoked.
     * e.g. 'File', 'Folder', 'List', etc.
     */
    objectType?: ObjectTypeValues;
}

